package app.vidloader;
import java.io.*;import java.util.*;import java.util.concurrent.*;
public final class MediaRemuxer{
 public interface Checkpoint{void check()throws IOException;}public interface Progress{void update(String phase,long done,long total)throws IOException;}
 static void run(List<String> args,Checkpoint c,Progress p,String phase)throws IOException{List<String> command=new ArrayList<>();command.add(System.getProperty("snagfox.ffmpeg"));command.addAll(Arrays.asList("-nostdin","-hide_banner","-loglevel","error","-y"));command.addAll(args);File log=new File(android.content.Context.root,"media-tool.log");Process job=new ProcessBuilder(command).redirectError(log).redirectOutput(ProcessBuilder.Redirect.DISCARD).start();long started=System.nanoTime();try{while(!job.waitFor(250,TimeUnit.MILLISECONDS)){c.check();p.update(phase,-1,0);if(System.nanoTime()-started>TimeUnit.MINUTES.toNanos(60))throw new IOException("Media processing timed out");}c.check();if(job.exitValue()!=0)throw new IOException("Media processing failed; see local media-tool.log");p.update(phase,1,1);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new InterruptedIOException("Processing cancelled");}finally{if(job.isAlive())job.destroyForcibly();}}
 public static void toContainer(File v,File a,File out,Checkpoint c,Progress p,boolean webm)throws IOException{List<String> args=new ArrayList<>(Arrays.asList("-i",v.getAbsolutePath()));if(a!=null)args.addAll(Arrays.asList("-i",a.getAbsolutePath(),"-map","0:v:0","-map","1:a:0"));else args.addAll(Arrays.asList("-map","0"));args.addAll(Arrays.asList("-c","copy",out.getAbsolutePath()));run(args,c,p,"assembling");}
}